import{_ as a,H as r,f as p,i as t}from"./chunks/framework.BH2BK_3i.js";const M=JSON.parse('{"title":"复习课（二）| MapReduce","description":"","frontmatter":{},"headers":[{"level":2,"title":"MapReduce介绍","slug":"mapreduce介绍","link":"#mapreduce介绍","children":[]},{"level":2,"title":"编程模型","slug":"编程模型","link":"#编程模型","children":[]},{"level":2,"title":"执行概览","slug":"执行概览","link":"#执行概览","children":[]},{"level":2,"title":"容错设计","slug":"容错设计","link":"#容错设计","children":[]},{"level":2,"title":"性能优化","slug":"性能优化","link":"#性能优化","children":[]},{"level":2,"title":"遗憾与缺陷","slug":"遗憾与缺陷","link":"#遗憾与缺陷","children":[]}],"relativePath":"大数据经典论文解读/复习课（二）-MapReduce.md","filePath":"大数据经典论文解读/复习课（二）-MapReduce.md","lastUpdated":1779819465000}'),c={name:"大数据经典论文解读/复习课（二）-MapReduce.md"};function o(s,e,d,l,n,u){return r(),p("div",null,[...e[0]||(e[0]=[t(`<h1 id="复习课-二-mapreduce" tabindex="-1">复习课（二）| MapReduce <a class="header-anchor" href="#复习课-二-mapreduce" aria-label="Permalink to &quot;复习课（二）| MapReduce&quot;">​</a></h1><p>你好，我是黄金。欢迎来到第二期复习课，今天我们来回顾MapReduce论文的知识点。</p><h2 id="mapreduce介绍" tabindex="-1">MapReduce介绍 <a class="header-anchor" href="#mapreduce介绍" aria-label="Permalink to &quot;MapReduce介绍&quot;">​</a></h2><p>在论文的第1节“Introduction”中，作者提到过去5年里，Google的同事们实现了上百个针对特定领域的大数据分析程序，这促使他们思考开发一种更通用的编程模型，让开发者能够专注于分析程序的业务逻辑，而不需要关心分布式领域的复杂问题。</p><p>MapReduce的编程模型也并非是作者首创，而是借鉴了Lisp这类函数式编程语言的思想。熟悉Java Stream API的同学对这种编程模式应该都不陌生，它实际上就是map、groupingBy、reduce之类的操作，这种编程模型 <strong>分离了程序的业务逻辑和控制逻辑</strong>，使得程序在大规模的分布式环境下运行成为了可能。</p><p>另外，尽管MapReduce编程模型非常简单，现实中的大多数任务却都可以用这种编程模型来表达，这在函数式编程语言中已经得到了证明，它为MapReduce后来广泛地流行奠定了基础。</p><p>在论文第6.1节“Large-Scale Indexing”中就给出了一个例子，说明用MapReduce重写的索引服务带来的显著收益：第一，代码更精简，也更容易理解，原来用来实现某个计算功能的代码有3800行，重构后只有700行；第二，性能更好，原来改变索引需要几个月，现在只要几天；第三，更容易维护，也更容易提升性能，因为分布式问题都交给了MapReduce框架来处理。</p><p>那么总结一下，MapReduce主要有三个特点。 <strong>第一，简单的编程模型；第二，丰富的表达能力；第三，能够有效利用分布式系统的资源。</strong></p><h2 id="编程模型" tabindex="-1">编程模型 <a class="header-anchor" href="#编程模型" aria-label="Permalink to &quot;编程模型&quot;">​</a></h2><p>使用MapReduce编程模型，只需要实现两个函数，一个是Map函数，另一个是Reduce函数。</p><p>Map函数，是接受一个key-value对，返回一组新的key-value对，它通常被用来做数据变换。而Reduce函数，是接受一个key，以及一组相关的value，然后返回一组新的value，它通常被用来做数据规约，比如分组计数。如果你对于API还不够清楚的话，可以参考下面的代码：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map: (k1, v1) -&gt; list (k2, v2)</span></span>
<span class="line"><span>reduce: (k2, list(v2)) -&gt; list(v3)</span></span></code></pre></div><h2 id="执行概览" tabindex="-1">执行概览 <a class="header-anchor" href="#执行概览" aria-label="Permalink to &quot;执行概览&quot;">​</a></h2><p>在论文的第3.1节“Execution Overview”中，描述了MapReduce的执行过程。</p><p>MapReduce会启动很多个Worker程序，有的负责map任务，有的负责reduce任务，其中有一个很特殊，叫做 <strong>Master</strong>，它负责整个MapReduce任务的调度。MapReduce把输入数据分成了M份，交给不同的map任务进行处理。每一份大概占用16~64MB，和GFS的Block块大小接近，相当于一个map任务处理一个或多个GFS Block块。</p><p>此外，map任务的处理结果是写在本地的，而reduce任务会通过RPC请求对应的机器，获取map任务的输出。map到reduce会经过一个 <strong>混洗</strong> 的过程，任何一个map任务的输出都可能被多个reduce任务读取。那么， <strong>map任务的输出如何对应多个reduce任务的输入呢？</strong></p><p>map任务在执行的时候知道存在多少个reduce任务，它的输出会按分区函数分成R份，每一份对应着一个reduce任务的输入。当所有的reduce任务执行完成之后，Master就会通知客户端任务结束。</p><p>那么，通过MapReduce的执行过程，我们可以看到数据的Block会分散在不同机器上，map和reduce的计算任务也分散在不同机器上，从而就有效利用了分布式系统的资源。</p><h2 id="容错设计" tabindex="-1">容错设计 <a class="header-anchor" href="#容错设计" aria-label="Permalink to &quot;容错设计&quot;">​</a></h2><p>分布式系统的局部出现故障是难以避免的事情，让我们来看看MapReduce都做了哪些设计，来保障系统的可靠性。</p><p>MapReduce程序由多个工作进程构成，进程可以分成两类，一类是 <strong>Master进程</strong>，只有一个，负责整个MapReduce任务的调度。另一类是 <strong>Worker进程</strong>，负责执行map任务和reduce任务。Worker进程只和Master进程交互，Worker和Worker进程之间没有交互。</p><p>需要注意的是，前面提到混洗过程map任务和reduce任务之间交互，并不是通过Worker和Worker进程交互完成的，而是绕过Worker进程，通过RPC服务交互。Worker进程的这种独立性使得当Worker进程崩溃的时候，只需要由Master进程重启，并重新运行其负责的map和reduce任务即可。</p><p>Master进程会掌握执行计划，通过心跳来获得Worker进程的执行进度和状态。如果我们把Master进程的状态保存下来，就很容易让Master进程从故障中恢复。</p><p>不过，在MapReduce的论文中，作者并没有实现这一点，这是因为作者认为Master进程是单实例，短周期执行，不太可能在运行的过程中出现故障，所以当Master进程出错时，作者希望用户重试MapReduce任务。</p><p>Master会通过心跳获悉Worker进程是否还在工作，不过当Master进程和Worker进程点之间的网络出现故障时，Master其实会产生误判，认为还在工作的Worker进程停止了工作，然后在其他地方启动了一个新的Worker进程，执行相同的任务。</p><p>那么，在这种故障恢复的机制下，系统就可能同时存在多个处理相同输入的map任务或reduce任务。当map任务和reduce任务执行完成后，Worker进程向Master进程提交任务的过程就必须是 <strong>原子性</strong> 的，只有这样，当Master收到一个任务结束的消息之后，才能忽略其他相同任务结束的消息。</p><h2 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h2><p>除此之外，徐老师在 <a href="https://time.geekbang.org/column/article/423598" target="_blank" rel="noreferrer">07讲</a> 中还提到过，MapReduce框架有两个和网络相关的性能优化，一个是 <strong>让计算靠近存储</strong>，另一个是 <strong>通过Combiner减少混洗阶段需要传输的数据</strong>。</p><p>计算靠近存储在论文中被称为Locality Optimization，从论文的“Figure 3”中我们可以看到Locality Optimization的威力，由于大部分数据可以从本地读取，它的数据读取速度会是写出速度的2~3倍。</p><p>然后，论文里还有一个优化，叫做 <strong>Backup Tasks</strong>。在分布式的环境下，会出现一些执行很慢的长尾任务，比如论文的第5.4节“Effect of Backup Tasks”中提到，在一个MapReduce程序中，程序已经运行了960秒，剩下5个reduce任务还未执行完，而这5个任务又花了300秒，导致程序的运行时间增加了44%。</p><p>这5个任务就是长尾任务，它们执行很慢不是因为需要大量的计算，而是由于所在机器的网络、硬盘等资源突然出现了问题，换一台机器执行其实就能很快完成。那么MapReduce的优化方法，正是在其他地方启动一模一样的后备任务，处理相同的输入，谁先完成就以谁的结果为准，这样就比较好地消除了长尾现象。</p><h2 id="遗憾与缺陷" tabindex="-1">遗憾与缺陷 <a class="header-anchor" href="#遗憾与缺陷" aria-label="Permalink to &quot;遗憾与缺陷&quot;">​</a></h2><p>在07讲的最后，徐老师讲到了MapReduce框架有 <strong>两个缺陷</strong>。一个是它还没有100%做到让用户意识不到“分布式”的存在，二个是性能还是不太理想，Worker进程初始化时间太长，需要写到文件系统的数据太多。</p><p>Worker进程初始化时间到底有多长呢？在论文的第5.2节“Grep”中，就给出了一份数据，这个任务总耗时是150秒，其中初始化Worker进程的时间是60秒，足足占了40%的时间。</p><p>虽然MapReduce框架还有不少缺陷，不过也正是因为这些缺陷的存在，才给了后来者机会，在以后的经典论文中，我们将会看到工程师们是如何激动地弥补这些缺陷的。</p><p>好了，针对课程中，MapReduce论文的解读和学习的总结与回顾就到这里了，我们下节复习课再见。</p>`,36)])])}const h=a(c,[["render",o]]);export{M as __pageData,h as default};
